SET local check_function_bodies = off;

CREATE TABLE "public"."achievement_index" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."index_archievment_id_seq") NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "name"        text                     NOT NULL DEFAULT '''Generic Archievment'''::text,
  "description" text,
  "xp_reward"   bigint,
  "gold_reward" bigint,
  "icon_url"    text,
  CONSTRAINT "index_archievment_name_key" UNIQUE (name),
  CONSTRAINT "index_archievment_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."achievement_index"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."achievements" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "acquired_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"           bigint                   NOT NULL DEFAULT '0'::bigint,
  "index_id"          bigint                   NOT NULL DEFAULT '0'::bigint,
  "reward_id"         bigint,
  "archievement_icon" text,
  CONSTRAINT "achievements_pkey" PRIMARY KEY (id),
  CONSTRAINT "index_limit" CHECK ((index_id >= 0)),
  CONSTRAINT "unique_user_achievement_index" UNIQUE (user_id, index_id)
);

ALTER TABLE "public"."achievements"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."challenges" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "name"            text                     NOT NULL DEFAULT 'Challenge#000'::text,
  "chall_reward_id" bigint,
  "group_id"        bigint,
  "description"     text,
  "completed"       boolean                  NOT NULL DEFAULT false,
  "task_id"         bigint,
  "user_id"         bigint,
  "rating"          smallint                 DEFAULT '0'::smallint,
  "requirement"     text,
  CONSTRAINT "challenges_pkey" PRIMARY KEY (id),
  CONSTRAINT "chk_challenge_rating" CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 10))))
);

ALTER TABLE "public"."challenges"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."character_stats" (
  "id"             bigint  GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."stats_id_seq") NOT NULL,
  "hp"             bigint  NOT NULL DEFAULT '20'::bigint,
  "strength"       integer NOT NULL DEFAULT 5,
  "speed"          integer NOT NULL DEFAULT 5,
  "stamina"        integer NOT NULL DEFAULT 5,
  "wisdom"         integer NOT NULL DEFAULT 5,
  "level"          integer NOT NULL DEFAULT 1,
  "xpTotal"        bigint  NOT NULL DEFAULT '0'::bigint,
  "xpCurrent"      bigint  NOT NULL DEFAULT '0'::bigint,
  "playerName"     text    NOT NULL,
  "gold"           bigint  NOT NULL DEFAULT '0'::bigint,
  "skin_index_id"  bigint,
  "user_id"        bigint,
  "monster_beaten" integer DEFAULT 0,
  "bosses_beaten"  integer DEFAULT 0,
  "players_beaten" integer DEFAULT 0,
  "gems"           integer DEFAULT 0,
  "premium coins"  integer DEFAULT 0,
  CONSTRAINT "character_stats_user_id_key" UNIQUE (user_id),
  CONSTRAINT "chk_stats_positive_values"
    CHECK (((hp >= 0) AND (strength >= 0) AND (speed >= 0) AND (stamina >= 0) AND (wisdom >= 0) AND (level >= 1) AND ("xpTotal" >= 0) AND ("xpCurrent" >= 0) AND (gold >= 0))),
  CONSTRAINT "day_task_check" CHECK ((level > 0)),
  CONSTRAINT "stats_pkey" PRIMARY KEY (id),
  CONSTRAINT "stats_playerName_key" UNIQUE ("playerName"),
  CONSTRAINT "stats_xp_rules_check"
    CHECK
    (((((level = 1) AND ("xpTotal" = "xpCurrent")) OR ((level <> 1) AND (("xpTotal")::double precision = ((("xpCurrent")::double precision + ((level)::double precision ^
    (2)::double precision)) + ((10 * level))::double precision)))) AND
    (("xpCurrent")::double precision <= (((((level + 1))::double precision ^ (2)::double precision) + ((10 * (level + 1)))::double precision) - (((level)::double precision ^
    (2)::double precision) + ((10 * level))::double precision)))))
);

ALTER TABLE "public"."character_stats"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."equipment" (
  "id"                    bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "current_upgrade_price" bigint,
  "level"                 bigint                   NOT NULL DEFAULT 1,
  "stats"                 jsonb                    NOT NULL,
  "acquired_at"           timestamp with time zone DEFAULT now(),
  "tool_index_id"         bigint,
  "character_id"          bigint,
  "is_equiped"            boolean                  DEFAULT false,
  "nickname"              text,
  CONSTRAINT "chk_equipment_level_positive" CHECK (((level >= 1) AND (current_upgrade_price >= 0))),
  CONSTRAINT "equipment_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."equipment"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."goal" (
  "id"             bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  "goal_reward_id" bigint,
  "group_id"       bigint,
  "description"    text,
  "start_date"     timestamp with time zone,
  "end_date"       timestamp with time zone,
  "user_id"        bigint,
  "rating"         smallint,
  "completed"      boolean                  DEFAULT false,
  "name"           text                     NOT NULL DEFAULT '''Goal#000'''::text,
  CONSTRAINT "check_rating" CHECK (((rating >= 1) AND (rating <= 5))),
  CONSTRAINT "chk_goal_dates" CHECK (((end_date IS NULL) OR (start_date IS NULL) OR (end_date >= start_date))),
  CONSTRAINT "chk_goal_rating" CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 5)))),
  CONSTRAINT "goal_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."goal"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."groups" (
