CREATE TABLE "public"."rewards" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "gold_reward" bigint                   NOT NULL DEFAULT '0'::bigint,
  "xp_reward"   bigint                   NOT NULL DEFAULT '0'::bigint,
  "xp_boost"    real                     NOT NULL DEFAULT '1'::real,
  "claimed_at"  timestamp with time zone,
  "user_id"     bigint,
  "gem_reward"  integer                  DEFAULT 0,
  CONSTRAINT "check_xp_boost" CHECK ((xp_boost >= (0)::double precision)),
  CONSTRAINT "chk_rewards_non_negative" CHECK (((gold_reward >= 0) AND (xp_reward >= 0) AND (xp_boost >= (0.0)::double precision))),
  CONSTRAINT "rewards_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."rewards"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."skin_index" (
