CREATE TABLE "public"."tasks" (
  "id"             bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."Example_id_seq") NOT NULL,
  "start_time"     timestamp with time zone NOT NULL DEFAULT now(),
  "end_time"       timestamp with time zone NOT NULL DEFAULT now(),
  "task_reward_id" bigint,
  "group_id"       bigint,
  "description"    text                     NOT NULL,
  "icon"           character varying        DEFAULT '📆'::character varying,
  "user_id"        bigint,
  "name"           text                     NOT NULL DEFAULT 'Task#000'::text,
  CONSTRAINT "Example_pkey" PRIMARY KEY (id),
  CONSTRAINT "chk_task_dates" CHECK (((end_time IS NULL) OR (start_time IS NULL) OR (end_time >= start_time))),
  CONSTRAINT "day_task_check" CHECK ((EXTRACT(day FROM start_time) = EXTRACT(day FROM end_time))),
  CONSTRAINT "time_check" CHECK (((end_time IS NULL) OR (start_time < end_time)))
