CREATE POLICY "Permitir lectura publica de achievement_index" ON "public"."achievement_index"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Gestionar mis logros obtenidos" ON "public"."achievements"
  FOR ALL
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Gestionar mis propios desafios" ON "public"."challenges"
  FOR ALL
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Modificar solo mis propios stats" ON "public"."character_stats"
  FOR UPDATE
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Ver stats propios o de otros jugadores" ON "public"."character_stats"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Gestionar mi propio equipamiento" ON "public"."equipment"
  FOR ALL
  TO "authenticated"
  USING ((character_id IN ( SELECT character_stats.id
   FROM public.character_stats
  WHERE (character_stats.user_id = public.get_current_user_id()))));

CREATE POLICY "Gestionar mis propias metas" ON "public"."goal"
  FOR ALL
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Ver y reclamar mis propias recompensas" ON "public"."rewards"
  FOR ALL
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Permitir lectura publica de skin_index" ON "public"."skin_index"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Gestionar mis propias tareas" ON "public"."tasks"
  FOR ALL
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE POLICY "Permitir lectura publica de tool_index" ON "public"."tool_index"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Usuarios pueden actualizar su propio perfil" ON "public"."users"
  FOR UPDATE
  TO "authenticated"
  USING ((inner_id = auth.uid()))
  WITH CHECK ((inner_id = auth.uid()));

CREATE POLICY "Usuarios pueden ver perfiles" ON "public"."users"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "inner_id_policy" ON "public"."users"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = inner_id));

CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

