COMMENT ON COLUMN "public"."character_stats"."gold" IS 'La moneda del juego, se pueden comprar amras, equipamiento y skins. Se obtien en recompensas';

COMMENT ON COLUMN "public"."character_stats"."hp" IS 'Vida, constituye la barra de salud. En un combate, cuando llega a 0, pierdes. Se incrementa con vida social y trabajo.';

COMMENT ON COLUMN "public"."character_stats"."id" IS 'Identificador de las estadísticas del personaje';

COMMENT ON COLUMN "public"."character_stats"."level" IS 'Nivel de progreso del jugador en su aventura. Todas las estadísticas se incrementan, especialmente la vida máxima';

COMMENT ON COLUMN "public"."character_stats"."playerName" IS 'Nombre del personaje que representa al jugador';

COMMENT ON COLUMN "public"."character_stats"."speed" IS 'Velocidad, decide quien comienza a atacar en un combate. Se incrementa mediante el deporte y el ocio.';

COMMENT ON COLUMN "public"."character_stats"."stamina" IS 'Estamina, constituye la barra de estamina, permite seguir atacando en combate repetidamente. Si está baja, el personaje usará el próximo turno para descansar. Se entrena con deporte y entrenamiento';

COMMENT ON COLUMN "public"."character_stats"."strength" IS 'Fuerza, en un combate dicta qué tan fuerte golpearás a tu adversario. Se potencia con entrenamiento y trabajo.';

COMMENT ON COLUMN "public"."character_stats"."wisdom" IS 'Representa el conocimiento del personaje. En un combate, potencia el ataque definitivo. Se mejora con trabajo y estudio';

COMMENT ON COLUMN "public"."character_stats"."xpCurrent" IS 'Experiencia acumulada del usuario para subir al próximo nivel';

COMMENT ON COLUMN "public"."character_stats"."xpTotal" IS 'Experiencia total ganada. Se obtiene en recompensas. Crucial para subir de nivel.';

COMMENT ON COLUMN "public"."equipment"."acquired_at" IS 'Fecha de adquisición';

COMMENT ON COLUMN "public"."equipment"."current_tool_tier" IS 'Tier de la herramienta en función de su calidad';

COMMENT ON COLUMN "public"."equipment"."current_upgrade_price" IS 'Precio al mejorar';

COMMENT ON COLUMN "public"."equipment"."stats" IS 'Estadísticas aportadas al juagador';

COMMENT ON COLUMN "public"."equipment"."type" IS 'Tipo de equipación';

COMMENT ON COLUMN "public"."goal"."completed" IS 'Estado de finalización';

COMMENT ON COLUMN "public"."goal"."end_date" IS 'Deadline del objetivo';

COMMENT ON COLUMN "public"."goal"."group_id" IS 'Identificador del grupo';

COMMENT ON COLUMN "public"."goal"."name" IS 'Nombre del objetivo';

COMMENT ON COLUMN "public"."goal"."rating" IS 'Autoevalución del usuario del 1 al 10 en función de su desempeño en el objetivo en cuestión';

COMMENT ON COLUMN "public"."goal"."visibility" IS 'Visibilidad del objetivo';

COMMENT ON COLUMN "public"."groups"."id" IS 'Identificador de los grupos de quehaceres';

COMMENT ON COLUMN "public"."groups"."user_id" IS 'Puntero ligado al usuario';

COMMENT ON COLUMN "public"."rewards"."claimed_at" IS 'Fecha de reclamación';

COMMENT ON COLUMN "public"."rewards"."user_id" IS 'Identificador del usuario ligado a la recompensa';

COMMENT ON COLUMN "public"."tasks"."activity_type" IS 'Tipo de actividad, puede ser una de 6: Entrenamiento, trabajo, estudio, deporte, vida social y ocio, cada una dando sus respectivas estadisticas';

COMMENT ON COLUMN "public"."tasks"."group_id" IS 'Identificador del grupo';

COMMENT ON COLUMN "public"."tasks"."icon" IS 'Icono (o emoji) de la tarea';

COMMENT ON COLUMN "public"."tasks"."name" IS 'Nombre de la tarea asignada';

COMMENT ON COLUMN "public"."tasks"."priority" IS 'Prioridad de la tarea';

COMMENT ON COLUMN "public"."tasks"."status" IS 'Estado, entre pendiente, en proceso, finalizada, completada o no completada';

COMMENT ON COLUMN "public"."tasks"."user_id" IS 'Identificador del usuario ligado a la tarea';

COMMENT ON COLUMN "public"."tasks"."visibility" IS 'Tipo de visibilidad de la tarea, pudiendo estar oculta, visible o borrada';

COMMENT ON COLUMN "public"."tool_index"."base_tool_tier" IS 'Tier base de la herramienta en función de su calidad al comprar';

COMMENT ON COLUMN "public"."tool_index"."base_upgrade_price" IS 'Precio inicial al mejorar';

COMMENT ON COLUMN "public"."tool_index"."max_level" IS 'Nivel maximo al que se puede subir';

COMMENT ON COLUMN "public"."tool_index"."purchase_price" IS 'Precio al comprar';

COMMENT ON COLUMN "public"."tool_index"."tool_type" IS 'Tipo de equipación';

COMMENT ON COLUMN "public"."tool_index"."upgrade_stat_buffs" IS 'Estadisticas otorgadas al mejorar un nivel';

COMMENT ON COLUMN "public"."users"."account_type" IS 'Plan de la cuenta contratado';

COMMENT ON COLUMN "public"."users"."created_at" IS 'Fecha de creación';

COMMENT ON COLUMN "public"."users"."email" IS 'Correo del usuario de la cuenta';

COMMENT ON COLUMN "public"."users"."id" IS 'Identificador de los usuarios en la BD';

COMMENT ON COLUMN "public"."users"."inner_id" IS 'Id interno ligado al auth de supabase';

COMMENT ON COLUMN "public"."users"."playerName" IS 'Nombre del personaje que representa al jugador';

COMMENT ON COLUMN "public"."users"."player_id" IS 'Id del jugador asociado al usuario';

COMMENT ON COLUMN "public"."users"."profile_url" IS 'Link para la foto de perfil';

COMMENT ON COLUMN "public"."users"."task_streak" IS 'Racha de tareas completadas del usuario';

COMMENT ON COLUMN "public"."users"."user_icon" IS 'Icono (o emoji) del jugador';

COMMENT ON COLUMN "public"."users"."xp_acc_boost" IS 'Bonus de experiencia de la cuenta por diferentes multiplicadores aplicados a su cuenta';

COMMENT ON TABLE "public"."achievement_index" IS 'Lista de todos los logros disponibles';

COMMENT ON TABLE "public"."achievements" IS 'Logros completados';

COMMENT ON TABLE "public"."challenges" IS 'Desafíos impuestos';

COMMENT ON TABLE "public"."character_stats" IS 'Estadísticas del jugador';

COMMENT ON TABLE "public"."equipment" IS 'Armas y herramientas del usuario';

COMMENT ON TABLE "public"."goal" IS 'Metas impuestas';

COMMENT ON TABLE "public"."groups" IS 'Grupos de tareas, desafios y metas';

COMMENT ON TABLE "public"."rewards" IS 'Recompensas de los desafios, tareas, logros y objetivos';

COMMENT ON TABLE "public"."skin_index" IS 'Tabla con todos los índices de las skins';

COMMENT ON TABLE "public"."tasks" IS 'Tareas del calendario';

COMMENT ON TABLE "public"."tool_index" IS 'Lista de herramientas';

